CREATE TABLE "financial_accounts"("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"type" TEXT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'BRL',"opening_balance" DOUBLE PRECISION NOT NULL DEFAULT 0,"current_balance" DOUBLE PRECISION NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX "financial_accounts_active_type_idx" ON "financial_accounts"("active","type");
CREATE TABLE "account_entries"("id" SERIAL PRIMARY KEY,"account_id" INTEGER NOT NULL REFERENCES "financial_accounts"("id"),"type" TEXT NOT NULL,"amount" DOUBLE PRECISION NOT NULL,"description" TEXT NOT NULL,"source_type" TEXT NOT NULL,"source_id" TEXT NOT NULL,"occurred_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"created_by" TEXT NOT NULL,UNIQUE("source_type","source_id","account_id"));
CREATE INDEX "account_entries_account_id_occurred_at_idx" ON "account_entries"("account_id","occurred_at");
CREATE TABLE "account_transfers"("id" SERIAL PRIMARY KEY,"from_account_id" INTEGER NOT NULL REFERENCES "financial_accounts"("id"),"to_account_id" INTEGER NOT NULL REFERENCES "financial_accounts"("id"),"amount" DOUBLE PRECISION NOT NULL,"description" TEXT,"transferred_by" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "account_transfers_created_at_idx" ON "account_transfers"("created_at");
CREATE TABLE "cash_register_sessions"("id" SERIAL PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"register_name" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'open',"opening_amount" DOUBLE PRECISION NOT NULL,"expected_amount" DOUBLE PRECISION,"closing_amount" DOUBLE PRECISION,"difference" DOUBLE PRECISION,"opened_by" TEXT NOT NULL,"closed_by" TEXT,"opened_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"closed_at" TIMESTAMPTZ);CREATE INDEX "cash_register_sessions_status_opened_at_idx" ON "cash_register_sessions"("status","opened_at");
CREATE TABLE "cash_register_events"("id" SERIAL PRIMARY KEY,"session_id" INTEGER NOT NULL REFERENCES "cash_register_sessions"("id") ON DELETE CASCADE,"type" TEXT NOT NULL,"amount" DOUBLE PRECISION NOT NULL,"description" TEXT NOT NULL,"actor" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "cash_register_events_session_id_created_at_idx" ON "cash_register_events"("session_id","created_at");
CREATE TABLE "bank_statement_imports"("id" SERIAL PRIMARY KEY,"account_id" INTEGER NOT NULL REFERENCES "financial_accounts"("id"),"file_name" TEXT NOT NULL,"digest" TEXT NOT NULL UNIQUE,"row_count" INTEGER NOT NULL,"imported_by" TEXT NOT NULL,"imported_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "bank_statement_imports_account_id_imported_at_idx" ON "bank_statement_imports"("account_id","imported_at");
CREATE TABLE "bank_transactions"("id" SERIAL PRIMARY KEY,"import_id" INTEGER NOT NULL REFERENCES "bank_statement_imports"("id") ON DELETE CASCADE,"account_id" INTEGER NOT NULL REFERENCES "financial_accounts"("id"),"external_id" TEXT NOT NULL,"occurred_at" DATE NOT NULL,"description" TEXT NOT NULL,"amount" DOUBLE PRECISION NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"matched_title_id" INTEGER REFERENCES "financial_titles"("id") ON DELETE SET NULL,"reconciled_by" TEXT,"reconciled_at" TIMESTAMPTZ,UNIQUE("account_id","external_id"));CREATE INDEX "bank_transactions_status_occurred_at_idx" ON "bank_transactions"("status","occurred_at");
CREATE TABLE "cost_centers"("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"code" TEXT NOT NULL UNIQUE,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "cost_centers_active_name_idx" ON "cost_centers"("active","name");
CREATE TABLE "budgets"("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"year" INTEGER NOT NULL,"scenario" TEXT NOT NULL DEFAULT 'base',"status" TEXT NOT NULL DEFAULT 'active',"created_by" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("name","year","scenario"));CREATE INDEX "budgets_year_status_idx" ON "budgets"("year","status");
CREATE TABLE "budget_lines"("id" SERIAL PRIMARY KEY,"budget_id" INTEGER NOT NULL REFERENCES "budgets"("id") ON DELETE CASCADE,"cost_center_id" INTEGER NOT NULL REFERENCES "cost_centers"("id"),"month" INTEGER NOT NULL,"revenue" DOUBLE PRECISION NOT NULL DEFAULT 0,"expense" DOUBLE PRECISION NOT NULL DEFAULT 0,UNIQUE("budget_id","cost_center_id","month"));
CREATE TABLE "business_goals"("id" SERIAL PRIMARY KEY,"title" TEXT NOT NULL,"metric" TEXT NOT NULL,"target" DOUBLE PRECISION NOT NULL,"current" DOUBLE PRECISION NOT NULL DEFAULT 0,"due_at" DATE NOT NULL,"status" TEXT NOT NULL DEFAULT 'active',"created_by" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "business_goals_status_due_at_idx" ON "business_goals"("status","due_at");
